:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --text: #eaeaea;
  --accent: #0f3460;
  --focus: #f5c542;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: radial-gradient(circle at 20% 30%, #0f3460 0%, transparent 40%),
                    radial-gradient(circle at 80% 70%, #e94560 0%, transparent 40%);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
  color: var(--text);
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--primary);
  border-radius: 0;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  box-shadow: 8px 8px 0 #000;
  image-rendering: pixelated;
}

.title {
  font-size: 1.75rem;
  font-weight: 800;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--primary);
  margin-bottom: 16px;
  text-shadow: 2px 2px 0 #000;
}

.mode-indicator {
  font-size: 1.125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text);
  margin-bottom: 8px;
  padding: 4px 12px;
  display: inline-block;
  border: 2px solid var(--primary);
  background: var(--accent);
}

.timer {
  font-size: 4.5rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  letter-spacing: 4px;
  margin: 16px 0 24px;
  color: var(--text);
  text-shadow: 4px 4px 0 #000;
  line-height: 1.1;
  word-break: break-word;
}

.controls,
.mode-switch {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.mode-switch {
  margin-top: 16px;
  padding-top: 16px;
  border-top: 2px dashed var(--accent);
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 12px 20px;
  min-width: 100px;
  color: var(--text);
  background: var(--accent);
  border: 3px solid var(--primary);
  border-radius: 0;
  cursor: pointer;
  box-shadow: 4px 4px 0 #000;
  transition: transform 0.05s, box-shadow 0.05s, background 0.15s;
}

.btn:hover {
  background: var(--primary);
  color: #fff;
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 #000;
}

.mode-btn {
  font-size: 0.875rem;
  min-width: 120px;
  padding: 10px 14px;
}

.mode-btn.active {
  background: var(--primary);
  color: #fff;
}

@media (max-width: 400px) {
  .timer {
    font-size: 3.5rem;
    letter-spacing: 2px;
  }
  .card {
    padding: 24px 16px;
  }
  .btn {
    min-width: 80px;
    padding: 10px 14px;
  }
  .mode-btn {
    min-width: 100px;
  }
}

const WORK_DURATION = 25 * 60;
const BREAK_DURATION = 5 * 60;

const timerEl = document.getElementById('timer');
const modeIndicator = document.getElementById('modeIndicator');
const startPauseBtn = document.getElementById('startPauseBtn');
const resetBtn = document.getElementById('resetBtn');
const workModeBtn = document.getElementById('workModeBtn');
const breakModeBtn = document.getElementById('breakModeBtn');

let currentMode = 'work';
let remaining = WORK_DURATION;
let intervalId = null;
let isRunning = false;

function formatTime(seconds) {
  const m = Math.floor(seconds / 60).toString().padStart(2, '0');
  const s = (seconds % 60).toString().padStart(2, '0');
  return `${m}:${s}`;
}

function updateDisplay() {
  timerEl.textContent = formatTime(remaining);
}

function setMode(mode) {
  currentMode = mode;
  remaining = mode === 'work' ? WORK_DURATION : BREAK_DURATION;
  modeIndicator.textContent = mode === 'work' ? 'Work' : 'Break';
  workModeBtn.classList.toggle('active', mode === 'work');
  breakModeBtn.classList.toggle('active', mode === 'break');
  workModeBtn.setAttribute('aria-pressed', mode === 'work');
  breakModeBtn.setAttribute('aria-pressed', mode === 'break');
  updateDisplay();
  stopTimer();
  startPauseBtn.textContent = 'Start';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function tick() {
  if (remaining > 0) {
    remaining--;
    updateDisplay();
  }
  if (remaining === 0) {
    stopTimer();
    startPauseBtn.textContent = 'Start';
    startPauseBtn.setAttribute('aria-label', 'Start timer');
    timerEl.textContent = '00:00';
  }
}

function startTimer() {
  if (isRunning) return;
  isRunning = true;
  intervalId = setInterval(tick, 1000);
  startPauseBtn.textContent = 'Pause';
  startPauseBtn.setAttribute('aria-label', 'Pause timer');
}

function stopTimer() {
  if (intervalId) {
    clearInterval(intervalId);
    intervalId = null;
  }
  isRunning = false;
}

function toggleStartPause() {
  if (isRunning) {
    stopTimer();
    startPauseBtn.textContent = 'Start';
    startPauseBtn.setAttribute('aria-label', 'Start timer');
  } else {
    startTimer();
  }
}

function resetTimer() {
  stopTimer();
  remaining = currentMode === 'work' ? WORK_DURATION : BREAK_DURATION;
  updateDisplay();
  startPauseBtn.textContent = 'Start';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

startPauseBtn.addEventListener('click', toggleStartPause);
resetBtn.addEventListener('click', resetTimer);
workModeBtn.addEventListener('click', () => setMode('work'));
breakModeBtn.addEventListener('click', () => setMode('break'));

updateDisplay();
